const VERSION='5.0.0';
const TZ='America/New_York';
const Y='https://www.youtube.com/watch?v=';
const COACH_UI='ui://dback/coach-v5.html';
let DB;
let PROGRAM;

const WARMUP=[
['Toe Spread / Toe Curl','10 slow reps','dVDMUuWtX00'],['Ankle CARs','5/side','vIDJiMShg4o'],['Controlled Knee Circles','8 each direction','92owncvIHlY'],['90/90 Hip Switches','8/side','m51AZSXMvEA'],['Hip CARs','5/side','PO1of6rKX3Q'],['Cat-Cow','8 slow reps','2of247Kt0tU'],['Thoracic Rotation','8/side','l3Ze_9iXL-M'],['Neck CARs','4/side','BsZmSx34hvQ'],['Shoulder CARs','5/side','ghXn2-ZYfU4'],['Scapular Push-Up','8 reps','NKekqeudgWs'],['Forearm Pronation / Supination','10 each','Y-2-lnALVZE'],['Wrist Mobility','10 each','zSzeOHqj1Sw'],['Glute Bridge','10 reps','wPM8icPu6H8'],['Dead Bug','6/side','zechBkcIMf0'],['Dead Hang / Wall Slide','20-30 sec / 8 reps','fq9gDvNZQ2c']];
const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const AI_INSTRUCTIONS=`You are DBACK AI Coach in Natural Human Coach Mode. Be an attentive, concise, highly competent personal trainer. Use tools whenever current workout, plan, history, profile, goals, progression or exercise video data is needed. During an active workout give one clear next action at a time. Understand shorthand like next, done, got 8, 40 pounds, too easy, too hard, show video, swap this exercise, start over, and stop. Never claim to see form unless an image or video was actually provided. If sharp pain, chest pain, fainting or severe shortness of breath is reported, stop training and advise appropriate medical evaluation.`;

const nowISO=()=>new Date().toISOString();
const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const day=()=>new Intl.DateTimeFormat('en-US',{timeZone:TZ,weekday:'long'}).format(new Date());
const slug=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const cors=()=>({'access-control-allow-origin':'*','access-control-allow-methods':'GET,POST,PUT,PATCH,DELETE,OPTIONS','access-control-allow-headers':'content-type,accept,mcp-session-id,mcp-protocol-version,last-event-id,authorization','access-control-expose-headers':'mcp-session-id,mcp-protocol-version','cache-control':'no-store','vary':'Origin, Accept'});
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{...cors(),'content-type':'application/json;charset=utf-8'}});
async function readJson(r){try{return await r.json()}catch{return{}}}
async function program(){if(PROGRAM)return PROGRAM;const r=await DB.prepare("SELECT value FROM app_config WHERE key='program'").first();if(!r?.value)throw Error('Workout program is not initialized');PROGRAM=JSON.parse(r.value);return PROGRAM}
async function cleanupStale(){await DB.prepare("UPDATE workout_sessions SET status='abandoned',completed_at=COALESCE(completed_at,?) WHERE status='active' AND workout_date<>?").bind(nowISO(),localDate()).run()}
async function exerciseState(id){return await DB.prepare('SELECT * FROM exercise_state WHERE exercise_id=?').bind(id).first()}
async function videoOverride(id){return await DB.prepare('SELECT * FROM video_overrides WHERE exercise_id=?').bind(id).first()}

async function dayPlan(d,{withState=true}={}){
 const all=await program(),p=all[d]||all.Monday;
 const ors=(await DB.prepare('SELECT * FROM exercise_overrides WHERE day_name=?').bind(d).all()).results||[];
 const om=new Map(ors.map(x=>[x.original_exercise_id,x]));
 const out=[];
 for(const a of p.slice(1)){
  const originalId=slug(a[0]),o=om.get(originalId),name=o?.replacement_name||a[0],id=slug(name),vo=await videoOverride(id);
  out.push({originalId,id,name,sets:o?.sets??a[1],reps:o?.reps??a[2],rest:o?.rest_seconds??a[3],rir:o?.rir??a[4],video:o?.video_url||vo?.video_url||Y+a[5],customized:!!o,state:withState?(await exerciseState(id)||null):undefined});
 }
 return{day:d,focus:p[0],targetMinutes:60,exercises:out};
}
async function workout(d=day()){
 await cleanupStale();const dp=await dayPlan(d);
 const vos=(await DB.prepare('SELECT * FROM video_overrides').all()).results||[],vm=new Map(vos.map(x=>[x.exercise_id,x.video_url]));
 const warmup=WARMUP.map(x=>({id:slug(x[0]),name:x[0],target:x[1],video:vm.get(slug(x[0]))||Y+x[2]}));
 const active=await DB.prepare("SELECT * FROM workout_sessions WHERE status='active' AND workout_date=? ORDER BY started_at DESC LIMIT 1").bind(localDate()).first();
 return{type:'workout',date:localDate(),...dp,warmup,activeSession:active||null,coachMode:'natural-human',version:VERSION};
}
async function fullPlan(){const days=[];for(const d of DAYS)days.push(await dayPlan(d,{withState:false}));return{type:'plan',days,version:VERSION}}
async function library(){
 const all=await program(),m=new Map();
 for(const [d,p] of Object.entries(all))for(const a of p.slice(1)){const id=slug(a[0]);if(!m.has(id))m.set(id,{id,name:a[0],sets:a[1],reps:a[2],rest:a[3],rir:a[4],video:Y+a[5],source:'program',days:[d]});else m.get(id).days.push(d)}
 for(const x of WARMUP){const id=slug(x[0]);if(!m.has(id))m.set(id,{id,name:x[0],sets:1,reps:x[1],rest:0,rir:null,video:Y+x[2],source:'warmup',days:['Warm-Up']})}
 const custom=(await DB.prepare('SELECT * FROM custom_exercises ORDER BY name').all()).results||[];for(const c of custom)m.set(c.id,{id:c.id,name:c.name,sets:c.sets||3,reps:c.reps||'8-12',rest:c.rest_seconds||60,rir:c.rir??2,video:c.video_url||'',source:'custom',days:[]});
 const vos=(await DB.prepare('SELECT * FROM video_overrides').all()).results||[],vm=new Map(vos.map(x=>[x.exercise_id,x.video_url]));for(const v of m.values())if(vm.has(v.id))v.video=vm.get(v.id);
 return{type:'library',exercises:[...m.values()].sort((a,b)=>a.name.localeCompare(b.name))};
}
async function findExercise(name){const q=String(name||'').trim().toLowerCase(),lib=(await library()).exercises;const e=lib.find(x=>x.name.toLowerCase()===q)||lib.find(x=>x.name.toLowerCase().includes(q)||q.includes(x.name.toLowerCase()));if(!e)throw Error('Exercise not found: '+name);return e}

async function start(a={}){await cleanupStale();const d=a.day||day();const existing=await DB.prepare("SELECT * FROM workout_sessions WHERE status='active' AND workout_date=? ORDER BY started_at DESC LIMIT 1").bind(localDate()).first();if(existing)return{...await workout(existing.day_name||d),activeSession:existing,resumed:true};const id=crypto.randomUUID(),ts=nowISO();await DB.prepare('INSERT INTO workout_sessions(id,workout_date,day_name,started_at,readiness,sleep_hours,bodyweight_lb,status) VALUES(?,?,?,?,?,?,?,?)').bind(id,localDate(),d,ts,a.readiness??null,a.sleep_hours??null,a.bodyweight_lb??null,'active').run();return{...await workout(d),activeSession:{id,day_name:d,started_at:ts,status:'active'},resumed:false}}
function repTop(spec){const s=String(spec||''),m=s.match(/(\d+)\s*[-–]\s*(\d+)/);if(m)return +m[2];const n=s.match(/^\s*(\d+)/);return n?+n[1]:null}
async function logSet(a){if(!a.session_id||!a.exercise_id||!a.set_number)throw Error('session_id, exercise_id and set_number are required');const session=await DB.prepare("SELECT * FROM workout_sessions WHERE id=? AND status='active'").bind(a.session_id).first();if(!session)throw Error('Active workout session not found');const ts=nowISO();await DB.prepare('INSERT INTO set_logs(session_id,exercise_id,set_number,weight_lb,reps,seconds,rir,rpe,discomfort,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(a.session_id,a.exercise_id,a.set_number,a.weight_lb??null,a.reps??null,a.seconds??null,a.rir??null,a.rpe??null,a.discomfort??0,ts).run();const prev=await exerciseState(a.exercise_id),w=a.weight_lb??prev?.last_weight_lb??null,r=a.reps??prev?.last_reps??null,secs=a.seconds??prev?.last_seconds??null;let nextW=w,nextR=null;const lib=(await library()).exercises.find(x=>x.id===a.exercise_id),hi=repTop(lib?.reps);if(w!=null&&r!=null&&hi&&r>=hi&&(a.rir==null||(a.rir>=1&&a.rir<=2)))nextW=Math.round((w+2.5)*2)/2;else if(r!=null&&hi)nextR=Math.min(hi,r+1);await DB.prepare(`INSERT INTO exercise_state(exercise_id,last_weight_lb,last_reps,last_seconds,last_rir,best_weight_lb,best_reps,best_seconds,next_weight_lb,next_reps_target,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(exercise_id) DO UPDATE SET last_weight_lb=excluded.last_weight_lb,last_reps=excluded.last_reps,last_seconds=excluded.last_seconds,last_rir=excluded.last_rir,best_weight_lb=MAX(COALESCE(exercise_state.best_weight_lb,0),COALESCE(excluded.last_weight_lb,0)),best_reps=MAX(COALESCE(exercise_state.best_reps,0),COALESCE(excluded.last_reps,0)),best_seconds=MAX(COALESCE(exercise_state.best_seconds,0),COALESCE(excluded.last_seconds,0)),next_weight_lb=excluded.next_weight_lb,next_reps_target=excluded.next_reps_target,updated_at=excluded.updated_at`).bind(a.exercise_id,w,r,secs,a.rir??null,w,r,secs,nextW,nextR,ts).run();const recommendation=nextW!=null&&w!=null&&nextW>w?`Next session target: ${nextW} lb if form stays clean.`:nextR?`Next target: ${nextR} reps at the same load.`:'Keep the current prescription and maintain clean form.';return{type:'set_logged',exercise_id:a.exercise_id,set_number:a.set_number,recommendation,state:await exerciseState(a.exercise_id)}}
async function finish(a){const x=await DB.prepare('SELECT * FROM workout_sessions WHERE id=?').bind(a.session_id).first();if(!x)throw Error('Workout session not found');if(x.status==='complete')return{type:'summary',alreadyComplete:true,duration_seconds:x.duration_seconds||0,sets:0,volume_lb_reps:0};const end=nowISO(),dur=Math.max(0,Math.floor((Date.parse(end)-Date.parse(x.started_at))/1000));await DB.prepare("UPDATE workout_sessions SET completed_at=?,duration_seconds=?,session_rpe=?,notes=?,status='complete' WHERE id=?").bind(end,dur,a.session_rpe??null,a.notes??null,a.session_id).run();const s=await DB.prepare('SELECT COUNT(*) count,SUM(COALESCE(weight_lb,0)*COALESCE(reps,0)) volume FROM set_logs WHERE session_id=?').bind(a.session_id).first();return{type:'summary',duration_seconds:dur,sets:+(s?.count||0),volume_lb_reps:+(s?.volume||0)}}
async function history(limit=20){const q=`SELECT w.*,COUNT(s.id) AS sets,COALESCE(SUM(COALESCE(s.weight_lb,0)*COALESCE(s.reps,0)),0) AS volume_lb_reps FROM workout_sessions w LEFT JOIN set_logs s ON s.session_id=w.id GROUP BY w.id ORDER BY w.started_at DESC LIMIT ?`;return{type:'history',sessions:(await DB.prepare(q).bind(Math.min(Math.max(+limit||20,1),100)).all()).results||[]}}
async function progress(id){return{type:'progress',exercise_id:id,state:await exerciseState(id),recent:(await DB.prepare('SELECT s.*,w.workout_date,w.day_name FROM set_logs s JOIN workout_sessions w ON w.id=s.session_id WHERE s.exercise_id=? ORDER BY s.completed_at DESC LIMIT 20').bind(id).all()).results||[]}}

async function profile(){return(await DB.prepare('SELECT * FROM user_profile WHERE id=1').first())||{id:1}}
async function saveProfile(a){await DB.prepare(`INSERT INTO user_profile(id,name,birth_date,height_in,weight_lb,timezone,primary_goal,units,updated_at) VALUES(1,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,birth_date=excluded.birth_date,height_in=excluded.height_in,weight_lb=excluded.weight_lb,timezone=excluded.timezone,primary_goal=excluded.primary_goal,units=excluded.units,updated_at=excluded.updated_at`).bind(a.name??null,a.birth_date??null,a.height_in??null,a.weight_lb??null,a.timezone||TZ,a.primary_goal??null,a.units||'imperial',nowISO()).run();return profile()}
async function goals(){return{type:'goals',goals:(await DB.prepare("SELECT * FROM goals ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, target_date, created_at DESC").all()).results||[]}}
async function saveGoal(a){const id=a.id||crypto.randomUUID(),ts=nowISO();await DB.prepare(`INSERT INTO goals(id,title,category,target_value,current_value,unit,target_date,status,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,category=excluded.category,target_value=excluded.target_value,current_value=excluded.current_value,unit=excluded.unit,target_date=excluded.target_date,status=excluded.status,notes=excluded.notes,updated_at=excluded.updated_at`).bind(id,a.title||'Goal',a.category||'general',a.target_value??null,a.current_value??null,a.unit??null,a.target_date??null,a.status||'active',a.notes??null,ts,ts).run();return await DB.prepare('SELECT * FROM goals WHERE id=?').bind(id).first()}
async function deleteGoal(id){await DB.prepare('DELETE FROM goals WHERE id=?').bind(id).run();return{deleted:true,id}}
async function metrics(){return{type:'metrics',metrics:(await DB.prepare('SELECT * FROM body_metrics ORDER BY recorded_at DESC LIMIT 100').all()).results||[]}}
async function saveMetric(a){const id=a.id||crypto.randomUUID(),ts=nowISO(),rec=a.recorded_at||localDate();await DB.prepare('INSERT INTO body_metrics(id,recorded_at,weight_lb,waist_in,body_fat_pct,chest_in,arm_in,thigh_in,resting_hr,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id,rec,a.weight_lb??null,a.waist_in??null,a.body_fat_pct??null,a.chest_in??null,a.arm_in??null,a.thigh_in??null,a.resting_hr??null,a.notes??null,ts).run();if(a.weight_lb!=null)await DB.prepare('UPDATE user_profile SET weight_lb=?,updated_at=? WHERE id=1').bind(a.weight_lb,ts).run();return await DB.prepare('SELECT * FROM body_metrics WHERE id=?').bind(id).first()}
async function photos(){return{type:'photos',photos:(await DB.prepare('SELECT id,recorded_at,label,notes,content_type,created_at FROM progress_photos ORDER BY recorded_at DESC,created_at DESC').all()).results||[]}}
async function uploadPhoto(env,r){if(!env.MEDIA)throw Error('Media storage is not configured');const f=await r.formData(),file=f.get('photo');if(!file||typeof file==='string')throw Error('Photo file is required');if(file.size>12*1024*1024)throw Error('Photo must be 12 MB or smaller');const type=file.type||'image/jpeg';if(!type.startsWith('image/'))throw Error('Only image uploads are supported');const id=crypto.randomUUID(),ext=(file.name?.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').slice(0,5)||'jpg',key=`progress/${localDate()}/${id}.${ext}`;await env.MEDIA.put(key,file.stream(),{httpMetadata:{contentType:type}});await DB.prepare('INSERT INTO progress_photos(id,recorded_at,object_key,label,notes,content_type,created_at) VALUES(?,?,?,?,?,?,?)').bind(id,String(f.get('recorded_at')||localDate()),key,String(f.get('label')||''),String(f.get('notes')||''),type,nowISO()).run();return{id,recorded_at:String(f.get('recorded_at')||localDate()),label:String(f.get('label')||''),notes:String(f.get('notes')||''),url:'/media/'+id}}
async function photoResponse(env,id){if(!env.MEDIA)return new Response('Media storage unavailable',{status:503});const row=await DB.prepare('SELECT * FROM progress_photos WHERE id=?').bind(id).first();if(!row)return new Response('Not found',{status:404});const obj=await env.MEDIA.get(row.object_key);if(!obj)return new Response('Not found',{status:404});const h=new Headers(cors());h.set('content-type',row.content_type||obj.httpMetadata?.contentType||'image/jpeg');h.set('cache-control','private, max-age=300');return new Response(obj.body,{headers:h})}
async function deletePhoto(env,id){const row=await DB.prepare('SELECT * FROM progress_photos WHERE id=?').bind(id).first();if(row&&env.MEDIA)await env.MEDIA.delete(row.object_key);await DB.prepare('DELETE FROM progress_photos WHERE id=?').bind(id).run();return{deleted:true,id}}
async function saveExerciseOverride(a){const d=a.day_name,orig=a.original_exercise_id;if(!DAYS.includes(d)||!orig)throw Error('day_name and original_exercise_id are required');const e=a.replacement_name?await findExercise(a.replacement_name).catch(()=>null):null;const name=a.replacement_name||e?.name;if(!name)throw Error('replacement_name is required');await DB.prepare(`INSERT INTO exercise_overrides(day_name,original_exercise_id,replacement_name,sets,reps,rest_seconds,rir,video_url,notes,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(day_name,original_exercise_id) DO UPDATE SET replacement_name=excluded.replacement_name,sets=excluded.sets,reps=excluded.reps,rest_seconds=excluded.rest_seconds,rir=excluded.rir,video_url=excluded.video_url,notes=excluded.notes,updated_at=excluded.updated_at`).bind(d,orig,name,a.sets??e?.sets??null,a.reps??e?.reps??null,a.rest_seconds??e?.rest??null,a.rir??e?.rir??null,a.video_url??e?.video??null,a.notes??null,nowISO()).run();return dayPlan(d,{withState:false})}
async function clearExerciseOverride(d,id){await DB.prepare('DELETE FROM exercise_overrides WHERE day_name=? AND original_exercise_id=?').bind(d,id).run();return dayPlan(d,{withState:false})}
async function saveVideo(a){if(!a.exercise_id||!a.video_url)throw Error('exercise_id and video_url are required');if(!/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//i.test(a.video_url))throw Error('Use a valid YouTube URL');await DB.prepare(`INSERT INTO video_overrides(exercise_id,video_url,title,source,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(exercise_id) DO UPDATE SET video_url=excluded.video_url,title=excluded.title,source=excluded.source,updated_at=excluded.updated_at`).bind(a.exercise_id,a.video_url,a.title??null,a.source||'user',nowISO()).run();return{saved:true,exercise_id:a.exercise_id,video_url:a.video_url}}
async function saveCustomExercise(a){const id=a.id||slug(a.name)||crypto.randomUUID();if(!a.name)throw Error('name is required');const ts=nowISO();await DB.prepare(`INSERT INTO custom_exercises(id,name,equipment,movement_pattern,sets,reps,rest_seconds,rir,video_url,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,equipment=excluded.equipment,movement_pattern=excluded.movement_pattern,sets=excluded.sets,reps=excluded.reps,rest_seconds=excluded.rest_seconds,rir=excluded.rir,video_url=excluded.video_url,notes=excluded.notes,updated_at=excluded.updated_at`).bind(id,a.name,a.equipment??null,a.movement_pattern??null,a.sets??3,a.reps||'8-12',a.rest_seconds??60,a.rir??2,a.video_url??null,a.notes??null,ts,ts).run();return await DB.prepare('SELECT * FROM custom_exercises WHERE id=?').bind(id).first()}
async function overview(){const [p,g,m,h,ph]=await Promise.all([profile(),goals(),metrics(),history(30),photos()]);const completed=h.sessions.filter(x=>x.status==='complete'),weekSeconds=completed.filter(x=>Date.now()-Date.parse(x.started_at)<7*86400000).reduce((s,x)=>s+(x.duration_seconds||0),0);return{type:'overview',profile:p,activeGoals:g.goals.filter(x=>x.status==='active'),latestMetric:m.metrics[0]||null,recentSessions:completed.slice(0,5),photoCount:ph.photos.length,weekMinutes:Math.round(weekSeconds/60),completed30:completed.length,version:VERSION}}

const fnTools=[
{type:'function',name:'get_today_workout',description:'Get today workout and active session.',parameters:{type:'object',properties:{day:{type:'string'}},additionalProperties:false}},
{type:'function',name:'get_weekly_plan',description:'Get the full seven day workout plan.',parameters:{type:'object',properties:{},additionalProperties:false}},
{type:'function',name:'start_workout',description:'Start or resume a tracked workout.',parameters:{type:'object',properties:{day:{type:'string'},readiness:{type:'integer'},sleep_hours:{type:'number'},bodyweight_lb:{type:'number'}},additionalProperties:false}},
{type:'function',name:'log_set',description:'Log a completed exercise set.',parameters:{type:'object',properties:{session_id:{type:'string'},exercise_id:{type:'string'},set_number:{type:'integer'},weight_lb:{type:'number'},reps:{type:'integer'},seconds:{type:'integer'},rir:{type:'number'},rpe:{type:'number'},discomfort:{type:'integer'}},required:['session_id','exercise_id','set_number'],additionalProperties:false}},
{type:'function',name:'complete_workout',description:'Complete the active workout.',parameters:{type:'object',properties:{session_id:{type:'string'},session_rpe:{type:'number'},notes:{type:'string'}},required:['session_id'],additionalProperties:false}},
{type:'function',name:'show_video',description:'Find the instructional video for an exercise.',parameters:{type:'object',properties:{exercise_name:{type:'string'}},required:['exercise_name'],additionalProperties:false}},
{type:'function',name:'get_history',description:'Get recent workout history.',parameters:{type:'object',properties:{limit:{type:'integer'}},additionalProperties:false}},
{type:'function',name:'get_progress',description:'Get exercise progression.',parameters:{type:'object',properties:{exercise_id:{type:'string'}},required:['exercise_id'],additionalProperties:false}},
{type:'function',name:'get_profile',description:'Get athlete profile.',parameters:{type:'object',properties:{},additionalProperties:false}},
{type:'function',name:'get_goals',description:'Get fitness goals.',parameters:{type:'object',properties:{},additionalProperties:false}}
];
async function callOpenAI(env,payload){const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{authorization:'Bearer '+env.OPENAI_API_KEY,'content-type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw Error(data?.error?.message||('OpenAI '+r.status));return data}
async function aiCoach(env,message,previous){if(!env.OPENAI_API_KEY)return{error:'OPENAI_API_KEY is not configured'};let data=await callOpenAI(env,{model:env.OPENAI_MODEL||'gpt-5.6-terra',instructions:AI_INSTRUCTIONS,input:String(message||''),tools:fnTools,tool_choice:'auto',store:true,max_output_tokens:650,...(previous?{previous_response_id:previous}:{})});const actions=[];for(let round=0;round<5;round++){const calls=(data.output||[]).filter(x=>x.type==='function_call');if(!calls.length)break;const outputs=[];for(const c of calls){let a={};try{a=JSON.parse(c.arguments||'{}')}catch{};let result;if(c.name==='get_today_workout')result=await workout(a.day||day());else if(c.name==='get_weekly_plan')result=await fullPlan();else if(c.name==='start_workout')result=await start(a);else if(c.name==='log_set')result=await logSet(a);else if(c.name==='complete_workout')result=await finish(a);else if(c.name==='show_video'){result=await findExercise(a.exercise_name);actions.push({type:'video',exercise:result})}else if(c.name==='get_history')result=await history(a.limit);else if(c.name==='get_progress')result=await progress(a.exercise_id);else if(c.name==='get_profile')result=await profile();else if(c.name==='get_goals')result=await goals();else result={error:'Unknown tool'};outputs.push({type:'function_call_output',call_id:c.call_id,output:JSON.stringify(result)})}data=await callOpenAI(env,{model:env.OPENAI_MODEL||'gpt-5.6-terra',instructions:AI_INSTRUCTIONS,previous_response_id:data.id,input:outputs,tools:fnTools,tool_choice:'auto',store:true,max_output_tokens:650})}const text=(data.output||[]).flatMap(x=>x.type==='message'?(x.content||[]):[]).filter(x=>x.type==='output_text').map(x=>x.text).join('\n').trim();return{id:data.id,text:text||'Ready.',actions}}
async function transcribe(env,r){if(!env.OPENAI_API_KEY)throw Error('OPENAI_API_KEY is not configured');const f=await r.formData(),file=f.get('audio');if(!file||typeof file==='string')throw Error('Audio file is required');const fd=new FormData();fd.append('model','gpt-transcribe');fd.append('file',file,file.name||'speech.webm');const rr=await fetch('https://api.openai.com/v1/audio/transcriptions',{method:'POST',headers:{authorization:'Bearer '+env.OPENAI_API_KEY},body:fd});const data=await rr.json();if(!rr.ok)throw Error(data?.error?.message||('Transcription '+rr.status));return{text:data.text||''}}
async function speech(env,text){if(!env.OPENAI_API_KEY)throw Error('OPENAI_API_KEY is not configured');const rr=await fetch('https://api.openai.com/v1/audio/speech',{method:'POST',headers:{authorization:'Bearer '+env.OPENAI_API_KEY,'content-type':'application/json'},body:JSON.stringify({model:'gpt-4o-mini-tts',voice:'alloy',input:String(text||'').slice(0,3500),response_format:'mp3'})});if(!rr.ok){let msg='Speech '+rr.status;try{const d=await rr.json();msg=d?.error?.message||msg}catch{}throw Error(msg)}return new Response(rr.body,{status:200,headers:{...cors(),'content-type':'audio/mpeg','cache-control':'no-store'}})}

const defs=[['open_coach','Open DBACK AI Coach','Use this when the user wants to open the interactive DBACK AI workout coach.',{},true],['get_today_workout','Get today workout','Use this when the user asks what to train today.',{day:{type:'string'}},true],['get_weekly_plan','Get weekly plan','Use this when the user asks to see the complete seven-day plan.',{},true],['start_workout','Start tracked workout','Use this when the user is ready to begin or resume a tracked workout.',{day:{type:'string'},readiness:{type:'integer',minimum:1,maximum:10},sleep_hours:{type:'number'},bodyweight_lb:{type:'number'}},false],['get_exercise_video','Show exercise video','Use this when the user asks for an instructional exercise video.',{exercise_name:{type:'string'}},true],['log_set','Log completed set','Use this when the user reports a completed set.',{session_id:{type:'string'},exercise_id:{type:'string'},set_number:{type:'integer'},weight_lb:{type:'number'},reps:{type:'integer'},seconds:{type:'integer'},rir:{type:'number'},rpe:{type:'number'},discomfort:{type:'integer'}},false],['complete_workout','Complete workout','Use this when the user finishes a workout.',{session_id:{type:'string'},session_rpe:{type:'number'},notes:{type:'string'}},false],['get_history','Get history','Use this when the user asks about workout history.',{limit:{type:'integer'}},true],['get_progress','Get progress','Use this when the user asks about progression for an exercise.',{exercise_id:{type:'string'}},true],['get_profile','Get profile','Use this when the user asks about their fitness profile.',{},true],['get_goals','Get goals','Use this when the user asks about their goals.',{},true]];
const mcpTools=defs.map(x=>({name:x[0],title:x[1],description:x[2],inputSchema:{type:'object',properties:x[3],required:x[0]==='get_exercise_video'?['exercise_name']:x[0]==='log_set'?['session_id','exercise_id','set_number']:x[0]==='complete_workout'?['session_id']:x[0]==='get_progress'?['exercise_id']:[]},annotations:{readOnlyHint:x[4],destructiveHint:false,openWorldHint:false},_meta:{ui:{resourceUri:COACH_UI},'openai/outputTemplate':COACH_UI}}));
const toolOut=(x,t='DBACK AI Coach updated.')=>({structuredContent:x,content:[{type:'text',text:t}]});
async function mcpCall(n,a={}){if(n==='open_coach'||n==='get_today_workout')return toolOut(await workout(a.day||day()));if(n==='get_weekly_plan')return toolOut(await fullPlan());if(n==='start_workout')return toolOut(await start(a),'Workout started.');if(n==='get_exercise_video'){const e=await findExercise(a.exercise_name);return toolOut({type:'video',exercise:e},e.name+' instructional video.');}if(n==='log_set')return toolOut(await logSet(a),'Set logged.');if(n==='complete_workout')return toolOut(await finish(a),'Workout complete.');if(n==='get_history')return toolOut(await history(a.limit));if(n==='get_progress')return toolOut(await progress(a.exercise_id));if(n==='get_profile')return toolOut({type:'profile',profile:await profile()});if(n==='get_goals')return toolOut(await goals());throw Error('Unknown tool')}
function widgetHtml(){return`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;background:#07111f;color:#fff;font:14px -apple-system,Segoe UI,sans-serif}.a{padding:14px}.c{background:#111827;border:1px solid #263247;border-radius:16px;padding:14px}.m{color:#94a3b8}.v{aspect-ratio:16/9;margin-top:10px}.v iframe{width:100%;height:100%;border:0;border-radius:10px}</style><div class=a><div class=c id=r>Loading…</div></div><script>(function(){var raw=(window.openai&&window.openai.toolOutput)||{},d=raw.structuredContent||raw||{},r=document.getElementById('r');if(d.type==='video'){var e=d.exercise||{},id='';try{id=new URL(e.video||'').searchParams.get('v')||''}catch(x){}r.innerHTML='<b>'+String(e.name||'Exercise')+'</b>'+(id?'<div class=v><iframe src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id)+'?rel=0&playsinline=1" allowfullscreen></iframe></div>':'<p>Video unavailable.</p>');return}r.innerHTML='<b>DBACK AI Coach '+VERSION+'</b><div class=m>Natural Human Coach Mode</div><p>'+(d.day||'Today')+' — '+(d.focus||d.type||'Fitness')+'</p>'})();<\/script>`}
const rpc=(id,result,status=200)=>new Response(JSON.stringify({jsonrpc:'2.0',id,result}),{status,headers:{...cors(),'content-type':'application/json','mcp-protocol-version':'2025-06-18'}});
async function mcp(r){let q;try{q=await r.json()}catch{return rpc(null,{isError:true,content:[{type:'text',text:'Parse error'}]},400)}const{id,method,params}=q;if(method==='initialize')return rpc(id,{protocolVersion:'2025-06-18',capabilities:{tools:{listChanged:false},resources:{subscribe:false,listChanged:false}},serverInfo:{name:'DBACK AI Coach',version:VERSION},instructions:AI_INSTRUCTIONS});if(id==null)return new Response(null,{status:202,headers:cors()});if(method==='ping')return rpc(id,{});if(method==='tools/list')return rpc(id,{tools:mcpTools});if(method==='resources/list')return rpc(id,{resources:[{uri:COACH_UI,name:'DBACK AI Coach',mimeType:'text/html;profile=mcp-app'}]});if(method==='resources/read'&&params?.uri===COACH_UI)return rpc(id,{contents:[{uri:COACH_UI,mimeType:'text/html;profile=mcp-app',text:widgetHtml(),_meta:{'openai/widgetDescription':'DBACK AI Coach workout and fitness dashboard.',ui:{prefersBorder:true,csp:{connectDomains:[],resourceDomains:['https://www.youtube-nocookie.com'],frameDomains:['https://www.youtube-nocookie.com']}}}}]});if(method==='tools/call'){try{return rpc(id,await mcpCall(params?.name,params?.arguments||{}))}catch(e){return rpc(id,{isError:true,content:[{type:'text',text:e.message}]})}}return rpc(id,{isError:true,content:[{type:'text',text:'Method not found'}]},404)}

function browserHtml(){return `<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name=theme-color content="#07111f"><title>DBACK AI Coach</title><style>
:root{--bg:#07111f;--panel:#0e1a2b;--panel2:#132238;--line:#243653;--text:#f8fafc;--muted:#94a3b8;--blue:#3b82f6;--green:#22c55e;--red:#ef4444;--gold:#f59e0b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{min-height:100vh}.topbar{position:sticky;top:0;z-index:30;display:flex;align-items:center;justify-content:space-between;padding:13px 18px;background:rgba(7,17,31,.95);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.brand{font-weight:900;letter-spacing:.3px}.sub{font-size:12px;color:#8ec5ff}.layout{display:grid;grid-template-columns:210px 1fr;max-width:1280px;margin:auto}.side{position:sticky;top:62px;height:calc(100vh - 62px);padding:16px;border-right:1px solid var(--line)}.nav{display:flex;flex-direction:column;gap:6px}.nav button,.mobileNav button{background:transparent;color:var(--muted);border:0;border-radius:11px;padding:11px;text-align:left;font-weight:700}.nav button.active,.mobileNav button.active{background:#172a45;color:#fff}.main{padding:20px;max-width:1040px;width:100%;margin:auto}.view{display:none}.view.active{display:block}.hero{padding:24px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,#142a4b,#0b1627)}.hero h1{font-size:30px;margin:6px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;margin:12px 0}.stat{font-size:28px;font-weight:900}.muted{color:var(--muted);font-size:12px}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.between{display:flex;justify-content:space-between;align-items:center;gap:10px}.btn{border:0;border-radius:11px;padding:10px 13px;background:#eef2f7;color:#0f172a;font-weight:800}.btn.blue{background:var(--blue);color:#fff}.btn.green{background:var(--green);color:#052e16}.btn.red{background:var(--red);color:#fff}.btn.ghost{background:#172238;color:#dbeafe;border:1px solid #304563}.tabs{display:flex;gap:7px;overflow:auto;padding:2px 0 10px}.tabs button{white-space:nowrap}.field{display:flex;flex-direction:column;gap:5px}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}input,select,textarea{width:100%;border:1px solid #31445f;border-radius:11px;background:#0b1627;color:#fff;padding:11px;font:inherit}textarea{min-height:82px}.exercise{border-top:1px solid #223650;padding:15px 0}.exercise:first-child{border-top:0}.setgrid{display:grid;grid-template-columns:70px 1fr 1fr 1fr auto;gap:7px;margin-top:10px}.warmgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.warmitem{border:1px solid #263a57;border-radius:13px;padding:11px}.timerbox{background:#091424;border:1px solid #2b4162;border-radius:13px;padding:9px 12px;min-width:110px}.timer{font-size:20px;font-weight:900;font-variant-numeric:tabular-nums}.messages{max-height:420px;overflow:auto}.msg{padding:11px 13px;border-radius:13px;margin:8px 0;white-space:pre-wrap}.me{background:#193758}.ai{background:#172238}.ask{display:grid;grid-template-columns:1fr auto auto;gap:8px}.videoDock{display:none;position:fixed;z-index:80;background:#050b13;border:1px solid #334b6c;box-shadow:0 20px 70px #0008}.videoDock.normal{display:block;right:18px;bottom:18px;width:min(520px,calc(100vw - 36px));border-radius:18px;padding:10px}.videoDock.mini{display:block;right:14px;bottom:82px;width:260px;border-radius:15px;padding:8px}.videoDock.full{display:block;inset:0;padding:18px;background:#02060c}.videoHead{display:flex;justify-content:space-between;gap:8px;align-items:center}.videoFrame{aspect-ratio:16/9;margin-top:8px}.videoDock.full .videoFrame{height:calc(100vh - 90px);aspect-ratio:auto}.videoFrame iframe{width:100%;height:100%;border:0;border-radius:10px}.modal{display:none;position:fixed;inset:0;z-index:90;background:#000a;align-items:center;justify-content:center;padding:18px}.modal.show{display:flex}.modalbox{background:#0e1a2b;border:1px solid #314b70;border-radius:20px;padding:18px;width:min(620px,100%);max-height:90vh;overflow:auto}.photoGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.photo{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#0b1627}.photo img{width:100%;aspect-ratio:4/5;object-fit:cover}.photo .p{padding:9px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:10px}.compare img{width:100%;border-radius:14px;max-height:560px;object-fit:cover}.goalbar{height:8px;background:#18263a;border-radius:999px;overflow:hidden}.goalbar i{display:block;height:100%;background:var(--green)}canvas{width:100%;height:220px;background:#091424;border-radius:12px}.statusDot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#64748b;margin-right:6px}.statusDot.on{background:var(--green)}.mobileNav{display:none}.toast{position:fixed;z-index:120;left:50%;bottom:90px;transform:translateX(-50%);background:#111827;border:1px solid #334155;padding:11px 15px;border-radius:12px;display:none}.toast.show{display:block}@media(max-width:800px){.layout{display:block}.side{display:none}.main{padding:12px 12px 86px}.grid,.grid2{grid-template-columns:1fr}.warmgrid{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}.setgrid{grid-template-columns:60px 1fr 1fr 1fr;}.setgrid button{grid-column:1/-1}.photoGrid{grid-template-columns:repeat(2,1fr)}.mobileNav{position:fixed;display:flex;bottom:0;left:0;right:0;z-index:40;background:#081321f5;border-top:1px solid var(--line);overflow:auto;padding:6px}.mobileNav button{min-width:74px;text-align:center;font-size:11px;padding:9px 6px}.hero h1{font-size:25px}.topbar{padding:11px 13px}}
</style></head><body><div class=shell><header class=topbar><div><div class=brand>DBACK AI COACH</div><div class=sub>Fitness OS · v${VERSION} · Natural Human Coach</div></div><div class=row><span id=health><span class=statusDot></span>Checking</span><button class="btn ghost" id=refreshBtn>Refresh</button></div></header><div class=layout><aside class=side><nav class=nav id=nav></nav></aside><main class=main>
<section class="view active" id=view-home></section><section class=view id=view-workout></section><section class=view id=view-plan></section><section class=view id=view-progress></section><section class=view id=view-history></section><section class=view id=view-coach></section><section class=view id=view-profile></section>
</main></div><nav class=mobileNav id=mobileNav></nav></div>
<div id=videoDock class="videoDock normal"><div class=videoHead><div><b id=videoTitle>Instruction Video</b><div class=muted id=videoMeta></div></div><div class=row><button class="btn ghost" id=videoMini>Minimize</button><button class="btn ghost" id=videoFull>Maximize</button><button class="btn red" id=videoClose>Close</button></div></div><div class=videoFrame><iframe id=videoFrame allow="accelerometer;autoplay;encrypted-media;gyroscope;picture-in-picture" allowfullscreen></iframe></div></div>
<div class=modal id=switchModal><div class=modalbox><div class=between><h3>Switch Exercise</h3><button class="btn ghost" data-close=switchModal>Close</button></div><p class=muted id=switchCurrent></p><div class=field><label>Replacement</label><select id=switchSelect></select></div><div class=row style="margin-top:12px"><button class="btn blue" id=switchSave>Save Replacement</button><button class="btn ghost" id=switchReset>Restore Original</button></div></div></div>
<div class=modal id=videoModal><div class=modalbox><div class=between><h3>Change Instruction Video</h3><button class="btn ghost" data-close=videoModal>Close</button></div><div class=field><label>YouTube URL</label><input id=videoUrl placeholder="https://www.youtube.com/watch?v=..."></div><button class="btn blue" id=videoSave style="margin-top:12px">Save Video</button></div></div>
<div class=toast id=toast></div><script>
(()=>{'use strict';
const VIEWS=[['home','Home'],['workout','Workout'],['plan','Full Plan'],['progress','Progress'],['history','History'],['coach','AI Coach'],['profile','Profile']];
let W=null,PLAN=null,LIB=null,OV=null,HIST=null,MET=null,GOALS=null,PHOTOS=null,PROFILE=null,session=null,restEnd=0,sessionTick=null,restTick=null,currentView='home',selectedPlanDay='Monday',switchCtx=null,videoCtx=null,prev=localStorage.getItem('dback_response_id')||'',recorder=null,stream=null,chunks=[],recording=false,hands=false,audioPlayer=null;
const $=id=>document.getElementById(id),esc=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){const e=$('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
async function api(path,opt){const r=await fetch(path,opt),text=await r.text();let j;try{j=JSON.parse(text)}catch{throw Error(text.slice(0,180)||('HTTP '+r.status))}if(!r.ok)throw Error(j.error||j.message||('HTTP '+r.status));return j}
function nav(){const h=VIEWS.map(([k,n])=>'<button data-view="'+k+'" class="'+(k===currentView?'active':'')+'">'+n+'</button>').join('');$('nav').innerHTML=h;$('mobileNav').innerHTML=h;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view))}
function show(v){currentView=v;document.querySelectorAll('.view').forEach(e=>e.classList.remove('active'));$('view-'+v).classList.add('active');nav();if(v==='plan')loadPlan();if(v==='progress')loadProgress();if(v==='history')loadHistory();if(v==='profile')loadProfile();if(v==='coach')renderCoach()}
function fmtTime(s){s=Math.max(0,Math.floor(s||0));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function youtubeId(u){try{const x=new URL(u);return x.hostname.includes('youtu.be')?x.pathname.slice(1):x.searchParams.get('v')||''}catch{return''}}
function openVideo(title,url,meta=''){const id=youtubeId(url);if(!id){toast('Video URL is not valid');return}videoCtx={title,url};$('videoTitle').textContent=title;$('videoMeta').textContent=meta;$('videoFrame').src='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id)+'?rel=0&playsinline=1';$('videoDock').className='videoDock normal'}
$('videoClose').onclick=()=>{$('videoDock').style.display='none';$('videoDock').className='videoDock normal';$('videoFrame').src=''};$('videoMini').onclick=()=>{$('videoDock').style.display='';$('videoDock').className='videoDock mini'};$('videoFull').onclick=()=>{$('videoDock').style.display='';$('videoDock').className='videoDock full'};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).classList.remove('show'));
async function health(){try{const h=await api('/health');$('health').innerHTML='<span class="statusDot on"></span>System online';return h}catch{$('health').innerHTML='<span class=statusDot></span>Offline'}}
async function loadAll(){await Promise.all([health(),loadToday(),loadOverview()]);nav()}
async function loadToday(){W=await api('/api/today');session=W.activeSession||null;renderWorkout();startTimers()}
async function loadOverview(){OV=await api('/api/overview');renderHome()}
function renderHome(){if(!OV)return;const p=OV.profile||{};$('view-home').innerHTML='<div class=hero><div class=muted>Welcome back</div><h1>'+esc(p.name||'Athlete')+'</h1><p>Your training, coaching, progression, goals and media are unified here.</p><div class=row><button class="btn green" id=quickStart>Start Today\'s Workout</button><button class="btn blue" data-homeview=plan>View Full Plan</button><button class="btn ghost" data-homeview=progress>Add Progress</button></div></div><div class=grid style="margin-top:12px"><div class=card><div class=muted>Training this week</div><div class=stat>'+esc(OV.weekMinutes)+' min</div></div><div class=card><div class=muted>Completed sessions</div><div class=stat>'+esc(OV.completed30)+'</div></div><div class=card><div class=muted>Progress photos</div><div class=stat>'+esc(OV.photoCount)+'</div></div></div><div class=grid2><div class=card><h3>Active Goals</h3>'+((OV.activeGoals||[]).length?OV.activeGoals.slice(0,4).map(goalHtml).join(''):'<p class=muted>No goals yet. Add one in Progress.</p>')+'</div><div class=card><h3>Latest Body Data</h3>'+metricSummary(OV.latestMetric)+'</div></div>';$('quickStart').onclick=async()=>{show('workout');await startWorkout()};document.querySelectorAll('[data-homeview]').forEach(b=>b.onclick=()=>show(b.dataset.homeview))}
function goalHtml(g){let pct=0;if(g.target_value!=null&&g.current_value!=null&&+g.target_value!==0)pct=Math.max(0,Math.min(100,Math.round((+g.current_value/+g.target_value)*100)));return'<div style="margin:12px 0"><div class=between><b>'+esc(g.title)+'</b><span class=muted>'+esc(g.current_value??'—')+' / '+esc(g.target_value??'—')+' '+esc(g.unit||'')+'</span></div><div class=goalbar><i style="width:'+pct+'%"></i></div></div>'}
function metricSummary(m){if(!m)return'<p class=muted>No body metrics yet.</p>';return'<div class=grid2><div><div class=muted>Weight</div><b>'+esc(m.weight_lb??'—')+' lb</b></div><div><div class=muted>Waist</div><b>'+esc(m.waist_in??'—')+' in</b></div><div><div class=muted>Body fat</div><b>'+esc(m.body_fat_pct??'—')+'%</b></div><div><div class=muted>Date</div><b>'+esc(m.recorded_at)+'</b></div></div>'}
async function startWorkout(){try{W=await api('/api/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({day:W?.day,readiness:8})});session=W.activeSession;renderWorkout();startTimers();toast(W.resumed?'Workout resumed':'Workout started')}catch(e){toast(e.message)}}
async function finishWorkout(){if(!session)return toast('No active workout');try{const z=await api('/api/complete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({session_id:session.id,session_rpe:8})});toast('Workout complete · '+Math.round(z.duration_seconds/60)+' min');session=null;restEnd=0;await loadToday();await loadOverview()}catch(e){toast(e.message)}}
function startTimers(){clearInterval(sessionTick);clearInterval(restTick);const update=()=>{const e=$('sessionTimer');if(e)e.textContent=session?.started_at?fmtTime((Date.now()-Date.parse(session.started_at))/1000):'00:00';const r=$('restTimer');if(r)r.textContent=restEnd?fmtTime((restEnd-Date.now())/1000):'00:00';if(restEnd&&Date.now()>=restEnd){restEnd=0;toast('Rest complete')}};update();sessionTick=setInterval(update,1000);restTick=sessionTick}
function renderWorkout(){if(!W)return;$('view-workout').innerHTML='<div class=hero><div class=between><div><div class=muted>'+esc(W.day)+' · '+esc(W.date)+'</div><h1>'+esc(W.focus)+'</h1><div class=muted>'+W.targetMinutes+' minute target · '+(session?'Tracking active':'Ready')+'</div></div><div class=row><div class=timerbox><div class=muted>Session</div><div class=timer id=sessionTimer>00:00</div></div><div class=timerbox><div class=muted>Rest</div><div class=timer id=restTimer>00:00</div></div></div></div><div class=row style="margin-top:12px"><button class="btn green" id=startBtn>'+(session?'Resume':'Start Workout')+'</button><button class="btn ghost" id=stopRest>Stop Rest</button><button class="btn red" id=finishBtn>Finish</button></div></div><div class=card><h3>Joint + Alignment Warm-Up</h3><div class=warmgrid>'+(W.warmup||[]).map((x,i)=>'<div class=warmitem><b>'+(i+1)+'. '+esc(x.name)+'</b><div class=muted>'+esc(x.target)+'</div><div class=row style="margin-top:7px"><button class="btn ghost" data-play="'+i+'" data-kind=warm>Video</button><button class="btn ghost" data-videoedit="'+esc(x.id)+'" data-videourl="'+esc(x.video)+'">Change Video</button></div></div>').join('')+'</div></div><div class=card><h3>Training</h3>'+(W.exercises||[]).map((e,i)=>exerciseHtml(e,i)).join('')+'</div>';$('startBtn').onclick=startWorkout;$('finishBtn').onclick=finishWorkout;$('stopRest').onclick=()=>{restEnd=0;startTimers()};document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{const x=b.dataset.kind==='warm'?W.warmup[+b.dataset.play]:W.exercises[+b.dataset.play];openVideo(x.name,x.video,b.dataset.kind==='warm'?x.target:(x.sets+' × '+x.reps))});document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>logExercise(+b.dataset.log));document.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>openSwitch(+b.dataset.switch));document.querySelectorAll('[data-videoedit]').forEach(b=>b.onclick=()=>openVideoEdit(b.dataset.videoedit,b.dataset.videourl));startTimers()}
function exerciseHtml(e,i){return'<div class=exercise><div class=between><div><b>'+esc(e.name)+'</b><div class=muted>'+esc(e.sets)+' sets × '+esc(e.reps)+' · '+esc(e.rest)+'s rest · '+esc(e.rir)+' RIR'+(e.customized?' · customized':'')+'</div><div class=muted>Previous: '+esc(e.state?.last_weight_lb??'—')+' lb × '+esc(e.state?.last_reps??'—')+' · Next: '+esc(e.state?.next_weight_lb??'—')+'</div></div><div class=row><button class="btn ghost" data-play="'+i+'" data-kind=exercise>Video</button><button class="btn ghost" data-switch="'+i+'">Switch</button><button class="btn ghost" data-videoedit="'+esc(e.id)+'" data-videourl="'+esc(e.video)+'">Change Video</button></div></div><div class=setgrid><input id=s'+i+' type=number min=1 value=1 title=Set><input id=w'+i+' type=number step=.5 placeholder="Weight lb"><input id=r'+i+' type=number placeholder=Reps><input id=i'+i+' type=number placeholder=RIR><button class="btn blue" data-log="'+i+'">Complete Set</button></div></div>'}
async function logExercise(i){if(!session)await startWorkout();if(!session)return;const e=W.exercises[i],num=k=>{const v=$(k+i).value;return v===''?null:+v},body={session_id:session.id,exercise_id:e.id,set_number:num('s')||1,weight_lb:num('w'),reps:num('r'),rir:num('i')};Object.keys(body).forEach(k=>body[k]===null&&delete body[k]);try{const z=await api('/api/log-set',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});restEnd=Date.now()+(+e.rest||60)*1000;toast('Set logged · '+z.recommendation);await loadToday()}catch(x){toast(x.message)}}
async function loadPlan(){PLAN=await api('/api/plan');LIB=LIB||await api('/api/library');selectedPlanDay=selectedPlanDay||W?.day||'Monday';renderPlan()}
function renderPlan(){if(!PLAN)return;const d=PLAN.days.find(x=>x.day===selectedPlanDay)||PLAN.days[0];$('view-plan').innerHTML='<div class=between><div><h1>Full 7-Day Plan</h1><p class=muted>Review every day, switch exercises, and customize instructional videos.</p></div></div><div class=tabs>'+PLAN.days.map(x=>'<button class="btn '+(x.day===selectedPlanDay?'blue':'ghost')+'" data-day="'+x.day+'">'+x.day+'</button>').join('')+'</div><div class=hero><div class=muted>'+esc(d.day)+'</div><h2>'+esc(d.focus)+'</h2><div>'+d.targetMinutes+' minute target</div></div><div class=card>'+d.exercises.map((e,i)=>'<div class=exercise><div class=between><div><b>'+esc(e.name)+'</b><div class=muted>'+esc(e.sets)+' × '+esc(e.reps)+' · '+esc(e.rest)+'s · '+esc(e.rir)+' RIR'+(e.customized?' · customized':'')+'</div></div><div class=row><button class="btn ghost" data-pvideo="'+i+'">Video</button><button class="btn ghost" data-pswitch="'+i+'">Switch</button><button class="btn ghost" data-pedit="'+esc(e.id)+'" data-url="'+esc(e.video)+'">Change Video</button></div></div></div>').join('')+'</div>';document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedPlanDay=b.dataset.day;renderPlan()});document.querySelectorAll('[data-pvideo]').forEach(b=>b.onclick=()=>{const e=d.exercises[+b.dataset.pvideo];openVideo(e.name,e.video,e.sets+' × '+e.reps)});document.querySelectorAll('[data-pswitch]').forEach(b=>openSwitchPlan(b,d,+b.dataset.pswitch));document.querySelectorAll('[data-pedit]').forEach(b=>b.onclick=()=>openVideoEdit(b.dataset.pedit,b.dataset.url))}
function openSwitchPlan(b,d,i){b.onclick=()=>{switchCtx={day:d.day,e:d.exercises[i],source:'plan'};fillSwitch()}}
function openSwitch(i){switchCtx={day:W.day,e:W.exercises[i],source:'workout'};fillSwitch()}
function fillSwitch(){if(!LIB)return toast('Exercise library loading');$('switchCurrent').textContent='Replace '+switchCtx.e.name+' on '+switchCtx.day;$('switchSelect').innerHTML=LIB.exercises.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+' · '+esc(x.source)+'</option>').join('');$('switchModal').classList.add('show')}
$('switchSave').onclick=async()=>{try{await api('/api/exercise/override',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({day_name:switchCtx.day,original_exercise_id:switchCtx.e.originalId,replacement_name:$('switchSelect').value})});$('switchModal').classList.remove('show');toast('Exercise replaced');await loadToday();await loadPlan()}catch(e){toast(e.message)}};$('switchReset').onclick=async()=>{try{await api('/api/exercise/override?day='+encodeURIComponent(switchCtx.day)+'&id='+encodeURIComponent(switchCtx.e.originalId),{method:'DELETE'});$('switchModal').classList.remove('show');toast('Original restored');await loadToday();await loadPlan()}catch(e){toast(e.message)}};
function openVideoEdit(id,url){videoCtx={id,url};$('videoUrl').value=url||'';$('videoModal').classList.add('show')}
$('videoSave').onclick=async()=>{try{await api('/api/video',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({exercise_id:videoCtx.id,video_url:$('videoUrl').value})});$('videoModal').classList.remove('show');toast('Instruction video updated');await loadToday();if(PLAN)await loadPlan();LIB=null}catch(e){toast(e.message)}};
async function loadProgress(){[MET,GOALS,PHOTOS]=await Promise.all([api('/api/metrics'),api('/api/goals'),api('/api/photos')]);renderProgress()}
function renderProgress(){const ms=MET?.metrics||[],gs=GOALS?.goals||[],ps=PHOTOS?.photos||[];$('view-progress').innerHTML='<h1>Progress Center</h1><div class=grid2><div class=card><h3>Add Body Metrics</h3><div class=formgrid><div class=field><label>Weight (lb)</label><input id=mWeight type=number step=.1></div><div class=field><label>Waist (in)</label><input id=mWaist type=number step=.1></div><div class=field><label>Body Fat %</label><input id=mFat type=number step=.1></div><div class=field><label>Resting HR</label><input id=mHr type=number></div></div><button class="btn blue" id=metricSave style="margin-top:10px">Save Measurement</button></div><div class=card><h3>Create Goal</h3><div class=field><label>Goal</label><input id=gTitle placeholder="Example: 175 lb body weight"></div><div class=formgrid><div class=field><label>Category</label><select id=gCat><option>body composition</option><option>strength</option><option>conditioning</option><option>mobility</option><option>habit</option></select></div><div class=field><label>Target date</label><input id=gDate type=date></div><div class=field><label>Current</label><input id=gCurrent type=number step=.1></div><div class=field><label>Target</label><input id=gTarget type=number step=.1></div></div><button class="btn green" id=goalSave style="margin-top:10px">Add Goal</button></div></div><div class=card><h3>Body Trend</h3><canvas id=metricChart width=900 height=220></canvas></div><div class=grid2><div class=card><h3>Goals</h3>'+(gs.length?gs.map(g=>goalHtml(g)+'<div class=row><button class="btn ghost" data-goaldone="'+g.id+'">Mark Complete</button><button class="btn red" data-goaldel="'+g.id+'">Delete</button></div>').join(''):'<p class=muted>No goals yet.</p>')+'</div><div class=card><h3>Progress Photos</h3><form id=photoForm><div class=field><label>Photo</label><input id=photoFile name=photo type=file accept="image/*"></div><div class=formgrid><div class=field><label>Date</label><input name=recorded_at type=date value="'+new Date().toISOString().slice(0,10)+'"></div><div class=field><label>Label</label><input name=label placeholder="Front, side, week 4..."></div></div><div class=field><label>Notes</label><textarea name=notes></textarea></div><button class="btn blue">Upload Photo</button></form></div></div><div class=card><div class=between><h3>Photo Timeline & Compare</h3><div class=muted>Select two photos below</div></div><div class=photoGrid>'+ps.map(p=>'<div class=photo><img loading=lazy src="/media/'+p.id+'"><div class=p><b>'+esc(p.label||p.recorded_at)+'</b><div class=muted>'+esc(p.recorded_at)+'</div><label><input type=checkbox data-compare="'+p.id+'"> Compare</label><button class="btn red" data-photodel="'+p.id+'">Delete</button></div></div>').join('')+'</div><div class=compare id=compareArea></div></div>';
 $('metricSave').onclick=saveMetric;$('goalSave').onclick=saveGoal;document.querySelectorAll('[data-goaldone]').forEach(b=>b.onclick=()=>updateGoalStatus(b.dataset.goaldone));document.querySelectorAll('[data-goaldel]').forEach(b=>b.onclick=()=>removeGoal(b.dataset.goaldel));$('photoForm').onsubmit=uploadPhoto;document.querySelectorAll('[data-photodel]').forEach(b=>b.onclick=()=>removePhoto(b.dataset.photodel));document.querySelectorAll('[data-compare]').forEach(b=>b.onchange=renderCompare);drawChart(ms)}
function drawChart(ms){const c=$('metricChart');if(!c)return;const ctx=c.getContext('2d'),arr=ms.filter(x=>x.weight_lb!=null).slice().reverse();ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#94a3b8';ctx.font='14px sans-serif';if(arr.length<2){ctx.fillText('Add at least two weight entries to build a trend.',20,35);return}const vals=arr.map(x=>+x.weight_lb),min=Math.min(...vals)-2,max=Math.max(...vals)+2;ctx.strokeStyle='#3b82f6';ctx.lineWidth=4;ctx.beginPath();arr.forEach((x,i)=>{const px=30+i*(c.width-60)/(arr.length-1),py=20+(max-+x.weight_lb)*(c.height-50)/(max-min);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.stroke();ctx.fillStyle='#cbd5e1';ctx.fillText(vals[0]+' lb',20,c.height-10);ctx.fillText(vals[vals.length-1]+' lb',c.width-80,c.height-10)}
async function saveMetric(){try{await api('/api/metrics',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({weight_lb:+$('mWeight').value||null,waist_in:+$('mWaist').value||null,body_fat_pct:+$('mFat').value||null,resting_hr:+$('mHr').value||null})});toast('Measurement saved');await loadProgress();await loadOverview()}catch(e){toast(e.message)}}
async function saveGoal(){try{await api('/api/goals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:$('gTitle').value,category:$('gCat').value,current_value:+$('gCurrent').value||null,target_value:+$('gTarget').value||null,target_date:$('gDate').value||null,status:'active'})});toast('Goal added');await loadProgress();await loadOverview()}catch(e){toast(e.message)}}
async function updateGoalStatus(id){const g=(GOALS.goals||[]).find(x=>x.id===id);if(!g)return;g.status='complete';await api('/api/goals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(g)});await loadProgress();await loadOverview()}
async function removeGoal(id){await api('/api/goals?id='+encodeURIComponent(id),{method:'DELETE'});await loadProgress();await loadOverview()}
async function uploadPhoto(ev){ev.preventDefault();try{const fd=new FormData(ev.currentTarget);await api('/api/photos',{method:'POST',body:fd});toast('Progress photo saved');await loadProgress();await loadOverview()}catch(e){toast(e.message)}}
async function removePhoto(id){if(!confirm('Delete this progress photo?'))return;await api('/api/photos?id='+encodeURIComponent(id),{method:'DELETE'});await loadProgress();await loadOverview()}
function renderCompare(){const ids=[...document.querySelectorAll('[data-compare]:checked')].slice(-2).map(x=>x.dataset.compare),area=$('compareArea');area.innerHTML=ids.map(id=>'<img src="/media/'+id+'">').join('')}
async function loadHistory(){HIST=await api('/api/history?limit=60');renderHistory()}
function renderHistory(){const ss=HIST?.sessions||[];$('view-history').innerHTML='<h1>Workout History</h1><div class=card>'+(ss.length?ss.map(s=>'<div class=exercise><div class=between><div><b>'+esc(s.day_name)+' · '+esc(s.workout_date)+'</b><div class=muted>'+esc(s.status)+' · '+Math.round((s.duration_seconds||0)/60)+' min · '+esc(s.sets||0)+' sets</div></div><div><b>'+Math.round(s.volume_lb_reps||0).toLocaleString()+'</b><div class=muted>lb-reps</div></div></div></div>').join(''):'<p class=muted>No history yet.</p>')+'</div>'}
async function loadProfile(){PROFILE=await api('/api/profile');LIB=LIB||await api('/api/library');renderProfile()}
function renderProfile(){const p=PROFILE||{};$('view-profile').innerHTML='<h1>Profile & Settings</h1><div class=grid2><div class=card><h3>Athlete Data</h3><div class=formgrid><div class=field><label>Name</label><input id=pName value="'+esc(p.name||'')+'"></div><div class=field><label>Birth date</label><input id=pBirth type=date value="'+esc(p.birth_date||'')+'"></div><div class=field><label>Height (in)</label><input id=pHeight type=number step=.1 value="'+esc(p.height_in||'')+'"></div><div class=field><label>Weight (lb)</label><input id=pWeight type=number step=.1 value="'+esc(p.weight_lb||'')+'"></div></div><div class=field><label>Primary goal</label><textarea id=pGoal>'+esc(p.primary_goal||'')+'</textarea></div><button class="btn blue" id=profileSave>Save Profile</button></div><div class=card><h3>Add Custom Exercise</h3><div class=field><label>Name</label><input id=cName></div><div class=formgrid><div class=field><label>Sets</label><input id=cSets type=number value=3></div><div class=field><label>Reps</label><input id=cReps value="8-12"></div><div class=field><label>Rest sec</label><input id=cRest type=number value=60></div><div class=field><label>RIR</label><input id=cRir type=number value=2></div></div><div class=field><label>YouTube video</label><input id=cVideo></div><button class="btn green" id=customSave>Add Exercise</button></div></div><div class=card><h3>Exercise Library</h3><p class=muted>'+esc(LIB?.exercises?.length||0)+' exercises available for substitutions.</p><div class=grid2>'+((LIB?.exercises||[]).slice(0,30).map(x=>'<div class=warmitem><b>'+esc(x.name)+'</b><div class=muted>'+esc(x.source)+' · '+esc(x.reps)+'</div></div>').join(''))+'</div></div>';$('profileSave').onclick=saveProfile;$('customSave').onclick=saveCustom}
async function saveProfile(){PROFILE=await api('/api/profile',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:$('pName').value,birth_date:$('pBirth').value||null,height_in:+$('pHeight').value||null,weight_lb:+$('pWeight').value||null,primary_goal:$('pGoal').value,timezone:'America/New_York',units:'imperial'})});toast('Profile updated');await loadOverview()}
async function saveCustom(){try{await api('/api/library/custom',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:$('cName').value,sets:+$('cSets').value,reps:$('cReps').value,rest_seconds:+$('cRest').value,rir:+$('cRir').value,video_url:$('cVideo').value})});LIB=await api('/api/library');toast('Custom exercise added');renderProfile()}catch(e){toast(e.message)}}
function renderCoach(){if($('view-coach').dataset.ready)return;$('view-coach').dataset.ready='1';$('view-coach').innerHTML='<h1>AI Coach</h1><div class=card><div class=between><div><b>Natural Human Coach Mode</b><div class=muted>Talk naturally. Your coach can read your plan, workout state, history, goals and progression.</div></div><button class="btn ghost" id=handsBtn>Hands-Free: Off</button></div><div id=messages class=messages><div class="msg ai">Ready. Tell me what you want to do.</div></div><div id=aiVideo></div><div class=ask><input id=prompt placeholder="Talk to your coach…"><button class="btn blue" id=micBtn>🎙</button><button class="btn blue" id=sendBtn>Send</button></div><div class=muted id=voiceStatus>Voice ready</div></div>';$('sendBtn').onclick=sendAI;$('prompt').onkeydown=e=>{if(e.key==='Enter')sendAI()};$('micBtn').onclick=toggleMic;$('handsBtn').onclick=()=>{hands=!hands;$('handsBtn').textContent='Hands-Free: '+(hands?'On':'Off')}}
function addMsg(cls,text){const d=$('messages'),e=document.createElement('div');e.className='msg '+cls;e.textContent=text;d.appendChild(e);d.scrollTop=d.scrollHeight}
async function sendAI(text){const input=$('prompt');const t=typeof text==='string'?text:input.value.trim();if(!t)return;input.value='';addMsg('me',t);$('voiceStatus').textContent='Coach thinking…';try{const z=await api('/api/coach',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:t,previous_response_id:prev||null})});if(z.id){prev=z.id;localStorage.setItem('dback_response_id',z.id)}const reply=z.text||z.error||'Ready.';addMsg('ai',reply);for(const a of z.actions||[])if(a.type==='video'&&a.exercise){openVideo(a.exercise.name,a.exercise.video,'AI-selected instruction');$('aiVideo').innerHTML='<div class=card><b>'+esc(a.exercise.name)+'</b><div class=muted>Video opened in the player. Minimize or maximize it anytime.</div></div>'}await Promise.all([loadToday(),loadOverview()]);await speak(reply)}catch(e){addMsg('ai','Error: '+e.message)}finally{$('voiceStatus').textContent='Voice ready'}}
async function speak(text){try{const r=await fetch('/api/speech',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text})});if(!r.ok)return;const blob=await r.blob();if(audioPlayer)audioPlayer.pause();audioPlayer=new Audio(URL.createObjectURL(blob));audioPlayer.onended=()=>{if(hands&&!recording)setTimeout(toggleMic,400)};await audioPlayer.play()}catch{}}
async function toggleMic(){if(recording){recorder?.stop();return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);recorder.onstop=async()=>{recording=false;$('micBtn').textContent='🎙';stream?.getTracks().forEach(t=>t.stop());$('voiceStatus').textContent='Transcribing…';try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'}),fd=new FormData();fd.append('audio',new File([blob],'speech.webm',{type:blob.type}));const z=await api('/api/transcribe',{method:'POST',body:fd});$('prompt').value=z.text||'';if(z.text)await sendAI(z.text)}catch(e){toast(e.message)}};recorder.start();recording=true;$('micBtn').textContent='■';$('voiceStatus').textContent='Listening…'}catch(e){toast('Microphone: '+e.message)}}
$('refreshBtn').onclick=()=>location.reload();nav();loadAll().catch(e=>toast(e.message));
})();
</script></body></html>`}

export default{async fetch(request,env){DB=env.DB;const u=new URL(request.url);if(request.method==='OPTIONS')return new Response(null,{status:204,headers:cors()});try{
 if(u.pathname==='/')return new Response(browserHtml(),{headers:{...cors(),'content-type':'text/html;charset=utf-8','cache-control':'no-store, no-cache, must-revalidate'}});
 if(u.pathname==='/health')return json({ok:true,service:'DBACK AI Coach',version:VERSION,database:!!env.DB,openaiConfigured:!!env.OPENAI_API_KEY,mediaConfigured:!!env.MEDIA,mcp:'/mcp'});
 if(u.pathname==='/api/overview')return json(await overview());
 if(u.pathname==='/api/today')return json(await workout(u.searchParams.get('day')||day()));
 if(u.pathname==='/api/plan')return json(await fullPlan());
 if(u.pathname==='/api/library'&&request.method==='GET')return json(await library());
 if(u.pathname==='/api/library/custom'&&request.method==='POST')return json(await saveCustomExercise(await readJson(request)));
 if(u.pathname==='/api/start'&&request.method==='POST')return json(await start(await readJson(request)));
 if(u.pathname==='/api/log-set'&&request.method==='POST')return json(await logSet(await readJson(request)));
 if(u.pathname==='/api/complete'&&request.method==='POST')return json(await finish(await readJson(request)));
 if(u.pathname==='/api/history')return json(await history(u.searchParams.get('limit')));
 if(u.pathname==='/api/progress')return json(await progress(u.searchParams.get('exercise_id')));
 if(u.pathname==='/api/profile'&&request.method==='GET')return json(await profile());
 if(u.pathname==='/api/profile'&&request.method==='POST')return json(await saveProfile(await readJson(request)));
 if(u.pathname==='/api/goals'&&request.method==='GET')return json(await goals());
 if(u.pathname==='/api/goals'&&request.method==='POST')return json(await saveGoal(await readJson(request)));
 if(u.pathname==='/api/goals'&&request.method==='DELETE')return json(await deleteGoal(u.searchParams.get('id')));
 if(u.pathname==='/api/metrics'&&request.method==='GET')return json(await metrics());
 if(u.pathname==='/api/metrics'&&request.method==='POST')return json(await saveMetric(await readJson(request)));
 if(u.pathname==='/api/photos'&&request.method==='GET')return json(await photos());
 if(u.pathname==='/api/photos'&&request.method==='POST')return json(await uploadPhoto(env,request));
 if(u.pathname==='/api/photos'&&request.method==='DELETE')return json(await deletePhoto(env,u.searchParams.get('id')));
 if(u.pathname.startsWith('/media/')&&request.method==='GET')return photoResponse(env,u.pathname.split('/').pop());
 if(u.pathname==='/api/exercise/override'&&request.method==='POST')return json(await saveExerciseOverride(await readJson(request)));
 if(u.pathname==='/api/exercise/override'&&request.method==='DELETE')return json(await clearExerciseOverride(u.searchParams.get('day'),u.searchParams.get('id')));
 if(u.pathname==='/api/video'&&request.method==='POST')return json(await saveVideo(await readJson(request)));
 if(u.pathname==='/api/coach'&&request.method==='POST'){const a=await readJson(request);return json(await aiCoach(env,a.message,a.previous_response_id))}
 if(u.pathname==='/api/transcribe'&&request.method==='POST')return json(await transcribe(env,request));
 if(u.pathname==='/api/speech'&&request.method==='POST'){const a=await readJson(request);return speech(env,a.text)}
 if(u.pathname==='/mcp'&&request.method==='POST')return mcp(request);
 if(u.pathname==='/mcp'&&request.method==='GET')return new Response('DBACK AI Coach MCP endpoint is online.',{status:405,headers:{...cors(),'content-type':'text/plain','allow':'POST, OPTIONS'}});
 return new Response('Not found',{status:404,headers:cors()});
 }catch(e){return json({error:e?.message||'Server error'},500)}}};
